edits:
.er-catalog-item{display:block;text-align:left;width:100%;border:1px solid transparent;background:transparent;color:var(--text);padding:12px 8px;border-radius:6px}.er-catalog-item:hover,.er-catalog-item:focus-visible{background:var(--hover);border-color:var(--accent)}.er-catalog-item small{display:block;color:var(--muted);margin-top:5px}

/* The actual edge SVG owns clipping, not a descendant svg. Keep the outer view clipped. */
#er-flow{overflow:hidden;isolation:isolate}
#er-flow svg.vue-flow__edges,#er-flow svg.vue-flow__connectionline{overflow:visible}
#er-flow .vue-flow__edge{stroke:var(--accent);cursor:pointer}
#er-flow .vue-flow__edge .vue-flow__edge-path{stroke:var(--accent);stroke-width:2;fill:none;vector-effect:non-scaling-stroke}
#er-flow .vue-flow__edge:hover .vue-flow__edge-path,#er-flow .vue-flow__edge.er-edge-hover .vue-flow__edge-path{stroke:var(--text);stroke-width:3}
#er-flow .vue-flow__edge.selected .vue-flow__edge-path,#er-flow .vue-flow__edge:focus-visible .vue-flow__edge-path{stroke:var(--accent);stroke-width:3.5}
#er-flow .vue-flow__edge .vue-flow__edge-interaction{stroke:transparent!important;fill:none;stroke-width:24;vector-effect:non-scaling-stroke;pointer-events:stroke}
#er-flow .vue-flow__edge-textwrapper{pointer-events:all;cursor:pointer}
#er-flow .vue-flow__edge-textbg{stroke:var(--line);stroke-width:1}
#er-flow .vue-flow__edge:hover .vue-flow__edge-textbg,#er-flow .vue-flow__edge.selected .vue-flow__edge-textbg,#er-flow .vue-flow__edge:focus-visible .vue-flow__edge-textbg{stroke:var(--accent);stroke-width:2}
#er-flow .er-cardinality{stroke:var(--accent);stroke-width:1.6;fill:none;pointer-events:none}
#er-flow .er-card:hover{border-color:var(--muted);background:var(--hover)}
#er-flow .er-card.selected{outline:2px solid var(--accent);outline-offset:1px;border-color:var(--accent)}
#er-flow .er-card.er-related{border-color:var(--accent)}
#er-flow .er-owned-field{background:var(--accent-soft);border-radius:3px;color:var(--text)}
#er-flow .vue-flow__node-erEntity:focus-visible{outline:2px dashed var(--text);outline-offset:6px;border-radius:8px}
#er-flow .er-card-heading button{min-height:26px;border-radius:3px;line-height:1.3}
#er-flow .er-card-heading button:hover:not(:disabled){color:var(--accent)}
#er-flow .er-card-heading button:active:not(:disabled){background:var(--accent-soft)}
#er-flow .er-card-heading button:focus-visible,#er-flow .er-section-frame button:focus-visible{outline:2px solid var(--accent);outline-offset:3px}
#er-flow .er-handle{height:20px!important;width:20px!important;border:2px solid var(--surface)!important;background:var(--accent)!important;border-radius:5px;box-sizing:border-box;z-index:4;transition:background-color .12s,border-color .12s}
#er-flow .er-port-target{border-radius:50%;background:var(--surface)!important;border-color:var(--accent)!important}
#er-flow .er-secondary-port{opacity:0}
#er-flow .er-card:hover .er-handle,#er-flow .er-card.selected .er-handle,#er-flow .vue-flow__node-erEntity:focus-within .er-handle,#er-flow.er-connecting .er-port-target{opacity:1}
#er-flow .er-handle:hover,#er-flow .er-handle:focus-visible,#er-flow .er-handle.connecting{background:var(--text)!important;border-color:var(--accent)!important;outline:2px solid var(--accent);outline-offset:2px}
#er-flow .er-port-target.valid{background:var(--green)!important;border-color:var(--surface)!important;outline:3px solid var(--green);outline-offset:2px}
#er-flow.er-connecting .er-port-source{opacity:.25;cursor:not-allowed}
#er-flow .er-section-frame{pointer-events:none}
#er-flow .er-section-frame button{pointer-events:auto;min-height:28px;padding:3px 8px;max-width:calc(100% - 32px);overflow:hidden;text-overflow:ellipsis;white-space:nowrap;border-radius:4px}
#er-flow .er-section-frame button:hover:not(:disabled){background:var(--accent-soft);color:var(--accent)}
#er-flow .er-section-frame button:active:not(:disabled){background:var(--hover)}
#er-guides{position:absolute;inset:0;width:100%;height:100%;z-index:8;pointer-events:none;overflow:hidden}
#er-guides line{stroke:var(--accent);stroke-width:1.5;stroke-dasharray:5 4;vector-effect:non-scaling-stroke}
.er-toolbar button,.er-canvas-caption label,.er-quick-properties .btn{min-height:32px}
.er-toolbar .segmented [aria-pressed=true]{background:var(--accent-soft);color:var(--accent);box-shadow:inset 0 0 0 1px var(--accent)}
.er-toolbar button:hover:not(:disabled),.er-quick-properties button:hover:not(:disabled){border-color:var(--accent)}
.er-toolbar button:active:not(:disabled),.er-catalog-item:active,.er-relationship-item:active{background:var(--accent-soft)}
.er-toolbar button:focus-visible,.er-catalog-item:focus-visible,.er-relationship-item:focus-visible{outline:2px solid var(--accent);outline-offset:2px}
.er-catalog-item[aria-pressed=true],.er-relationship-item[aria-pressed=true]{background:var(--accent-soft);border-color:var(--accent)}
.er-catalog-item strong,.er-catalog-item small{overflow-wrap:anywhere}
.er-canvas-options{display:flex;align-items:center;gap:12px;margin-left:auto;flex-wrap:wrap}
.er-canvas-options label{display:flex;align-items:center;gap:6px;cursor:pointer}.er-canvas-options input{accent-color:var(--accent);width:16px;height:16px}
#er-zoom-level{font-variant-numeric:tabular-nums;min-width:38px;text-align:right;color:var(--muted)}
.er-canvas-caption{gap:8px;min-height:48px}.er-canvas-caption>label{margin-left:0}
.er-legend{font-size:11px;line-height:1.6}
.er-relationship-list{padding:20px;overflow:auto;max-height:650px}.er-relationship-list>article{padding:12px 0;border-bottom:1px solid var(--line)}
.er-relationship-item{display:flex;flex-direction:column;gap:8px;background:transparent;border:1px solid transparent;color:var(--text);width:100%;padding:12px;text-align:left;border-radius:6px;cursor:pointer;overflow-wrap:anywhere}
.er-relationship-item strong{font-size:15px}.er-relationship-item small{color:var(--muted);line-height:1.6}.er-relationship-item:hover{border-color:var(--accent);background:var(--hover)}
.er-relationship-list>article>.btn{margin:8px 12px}
.er-inspector .er-meaning,.er-meaning{line-height:1.65}.er-properties code{overflow-wrap:anywhere;min-width:0}.er-properties span{flex-shrink:0}
.er-quick-properties{display:flex;flex-wrap:wrap;align-items:center;gap:8px;margin:12px 0 20px}.er-quick-properties>span{font-size:12px;color:var(--muted)}
.er-default small{display:block;color:var(--muted);margin-top:6px;line-height:1.5}.er-reference-example{white-space:pre-wrap;overflow-wrap:anywhere;font-size:12px;padding:12px;background:var(--bg);border-radius:4px}
.er-align-controls{margin:16px 0}.er-readonly .er-handle{pointer-events:none;opacity:.25}
.er-toolbar button:disabled,.er-readonly button:disabled{opacity:.45;cursor:not-allowed;box-shadow:none}
@media(prefers-reduced-motion:reduce){#er-flow .er-handle{transition:none}}
@media(max-width:700px){.er-canvas-caption{align-items:flex-start}.er-canvas-options{margin-left:0}.er-toolbar button{min-height:36px}.er-legend{font-size:11px}.er-quick-properties .btn{flex:0 1 auto}.er-inspector{padding:20px}.er-properties{max-width:100%}}

/* Press feedback is scoped to this editor and its protected form. */
.er-workspace .btn:active:not(:disabled),.er-toolbar .btn:active:not(:disabled),#modal.semantic-modal .btn:active:not(:disabled){box-shadow:inset 0 0 0 1px var(--accent);filter:brightness(.92)}
